package android.app;import android.content.*;public class Dialog implements DialogInterface{public static Dialog last;public android.view.View content;public boolean showing;Context c;android.view.Window window;public DialogInterface.OnDismissListener dismiss;public DialogInterface.OnKeyListener key;public Dialog(Context ctx){c=ctx;last=this;window=new android.view.Window(c);}public boolean requestWindowFeature(int f){return true;}public void setContentView(android.view.View v){content=v;}public void show(){showing=true;last=this;}public void dismiss(){boolean was=showing;showing=false;if(was && dismiss!=null)dismiss.onDismiss(this);}public boolean isShowing(){return showing;}public android.view.Window getWindow(){return window;}public void setOnDismissListener(DialogInterface.OnDismissListener l){dismiss=l;}public void setOnKeyListener(DialogInterface.OnKeyListener l){key=l;}}